use std::collections::HashSet;

fn has_common_element(a: Vec<i32>, b: Vec<i32>) -> bool {
    // We build a hash set out of the smaller vector to minimize memory usage.
    let (small, large) = if a.len() <= b.len() { (a, b) } else { (b, a) };

    let mut seen = HashSet::with_capacity(small.len());
    for x in small {
        seen.insert(x);
    }

    for y in large {
        if seen.contains(&y) {
            return true;
        }
    }

    false
}

